// Pega os dados dos nós anteriores
const usuario = $('Para Cada Usuário').item.json;
const memorias = $('Buscar Memória do Usuário').all().map(m => m.json.content).join('\n- ');
const tema = $('Buscar Tema da Semana').first().json;
const dataHoje = new Date().toLocaleDateString('pt-BR', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });

const prompt = `Você é o Zakar, o agente do devocional matinal.

Sua missão é gerar uma palavra personalizada, poderosa e cirúrgica para ${usuario.name} hoje, ${dataHoje}.

TEMA DA SEMANA: ${tema.theme_name} — ${tema.description}

CONTEXTO DO USUÁRIO:
- Nome: ${usuario.name}
- Momento de vida: ${usuario.life_stage}
- Fragmentos de memória recentes:
- ${memorias || 'Usuário novo, sem histórico ainda.'}

INSTRUÇÕES:
1. Escolha UM versículo (NVI) que seja precisamente relevante para o momento de vida do usuário e para o tema da semana. Não use versículos genéricos como João 3:16 ou Jeremias 29:11 a não ser que sejam realmente os mais precisos.
2. Escreva uma palavra de 180-220 palavras que:
   - Comece direto, NUNCA com "Bom dia!" genérico
   - Conecte o versículo com a situação real do usuário usando os fragmentos de memória
   - Use linguagem simples, próxima, como um amigo de confiança
3. Escreva uma pergunta de reflexão (1 linha)
4. Escreva uma ação prática para o dia (1 linha, algo pequeno e concreto)

RESPONDA APENAS com um JSON válido, sem markdown, sem explicações:
{
  "verse_reference": "Livro Cap:Ver",
  "verse_text": "texto completo do versículo (NVI)",
  "content": "palavra completa aqui",
  "reflection_question": "pergunta aqui",
  "action_of_day": "ação aqui"
}`;

return {
  user_id: usuario.id,
  user_name: usuario.name,
  prompt: prompt
};

const resposta = $json.choices[0].message.content;
let devocional;

try {
  devocional = JSON.parse(resposta);
} catch (e) {
  // Se a IA retornou algo fora do JSON, loga e pula esse usuário
  console.error('Erro ao parsear resposta da IA:', resposta);
  return null;
}

const userId = $('Montar Prompt do Despertar').item.json.user_id;
const hoje = new Date().toISOString().split('T')[0]; // YYYY-MM-DD

return {
  user_id: userId,
  date: hoje,
  verse_reference: devocional.verse_reference,
  verse_text: devocional.verse_text,
  content: devocional.content,
  reflection_question: devocional.reflection_question,
  action_of_day: devocional.action_of_day,
  agent_used: 'despertar'
};

const userId = $('Parsear Resposta da IA').item.json.user_id;
const versiculo = $('Parsear Resposta da IA').item.json.verse_reference;
console.log(`✅ Despertar gerado para usuário ${userId} — ${versiculo}`);
return { status: 'ok', user_id: userId, verse: versiculo };

