CREATE OR REPLACE FUNCTION atualizar_streak(p_user_id UUID)
RETURNS VOID AS $$
DECLARE
  v_last_read TIMESTAMPTZ;
  v_current_streak INT;
BEGIN
  SELECT last_read_at, streak_current
  INTO v_last_read, v_current_streak
  FROM user_profiles
  WHERE id = p_user_id;

  IF v_last_read IS NULL OR v_last_read < NOW() - INTERVAL '2 days' THEN
    -- Streak quebrado ou usuário novo
    UPDATE user_profiles
    SET streak_current = 1,
        last_read_at = NOW()
    WHERE id = p_user_id;
  ELSIF DATE(v_last_read) < DATE(NOW()) THEN
    -- Novo dia, incrementa streak
    UPDATE user_profiles
    SET streak_current = streak_current + 1,
        streak_best = GREATEST(streak_best, streak_current + 1),
        last_read_at = NOW()
    WHERE id = p_user_id;
  END IF;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

