const classificacao = $json.choices[0].message.content.trim().toLowerCase();
const agentesValidos = ['historiador', 'conselheiro', 'doutrinador', 'especialista'];
const agente = agentesValidos.includes(classificacao) ? classificacao : 'conselheiro';

return {
  agente,
  user_id: $('Webhook Entrada').item.json.body.user_id,
  message: $('Webhook Entrada').item.json.body.message,
  context_book: $('Webhook Entrada').item.json.body.context_book || null,
  context_chapter: $('Webhook Entrada').item.json.body.context_chapter || null,
  context_verse: $('Webhook Entrada').item.json.body.context_verse || null,
  verse_text: $('Webhook Entrada').item.json.body.verse_text || null
};

const dados = $('Extrair Agente').item.json;
const memorias = $('Buscar Memória RAG').all().map(m => m.json.content).filter(Boolean).join('\n- ');
const perfil = $('Buscar Perfil do Usuário').first().json;

const systemPrompts = {
  historiador: `Você é O Historiador, agente do Zakar especializado em Antigo Testamento.
Sua especialidade: contexto histórico, reis de Israel e Judá, profetas, arqueologia bíblica.
Tom: professoral, apaixonado, conta histórias com detalhes vívidos.
Estilo: 'Imagina que você está em 600 a.C., em Jerusalém sitiada...'`,

  conselheiro: `Você é O Conselheiro, agente do Zakar especializado em Livros de Sabedoria.
Sua especialidade: Salmos, Provérbios, Eclesiastes, Cantares, Jó. Aplicação prática à vida.
Tom: empático, cuidadoso, nunca minimiza a dor.
Estilo: conecta o texto bíblico com a situação real do usuário.`,

  doutrinador: `Você é O Doutrinador, agente do Zakar especializado em Novo Testamento.
Sua especialidade: Evangelhos, Epístolas de Paulo, graça, salvação, vida cristã prática.
Tom: firme, claro, acessível. Explica teologia sem jargão.
Estilo: 'Justificação, em termos simples, é como se sua ficha criminal fosse apagada...'`,

  especialista: `Você é A Especialista Temática, agente do Zakar.
Sua especialidade: temas transversais por toda a Bíblia, biografias bíblicas completas, tipologia, simbolismo.
Tom: entusiasmado, conecta pontos de forma fascinante.
Estilo: 'Sabia que tem pelo menos 7 mulheres chamadas Maria na Bíblia?'`
};

const system = systemPrompts[dados.agente] || systemPrompts.conselheiro;

const contextoPerfil = perfil ? `- Nome: ${perfil.name}\n- Momento de vida: ${perfil.life_stage}` : '';
const contextoMemoria = memorias ? `- Fragmentos de memória relevantes:\n- ${memorias}` : '- Sem histórico ainda.';
const contextoLeitura = dados.verse_text ? `- Leitura atual: ${dados.context_book} ${dados.context_chapter}:${dados.context_verse}\n- Texto: "${dados.verse_text}"` : '';

const userPrompt = `CONTEXTO DO USUÁRIO:\n${contextoPerfil}\n${contextoMemoria}\n${contextoLeitura}\n\nREGRAS:\n1. Máximo 250 palavras\n2. Nunca invente textos bíblicos\n3. Finalize com uma pergunta ou reflexão\n4. Linguagem acessível, sem jargão teológico sem explicação\n\nPergunta: ${dados.message}`;

return {
  agente: dados.agente,
  user_id: dados.user_id,
  message: dados.message,
  system_prompt: system,
  user_prompt: userPrompt
};

const resposta = $json.choices[0].message.content;
const dados = $('Montar Prompt do Agente').item.json;

return {
  resposta,
  agente: dados.agente,
  user_id: dados.user_id,
  pergunta: dados.message
};

const { user_id, journey_day_id, questions } = $json.body;

// Calcula quantas respostas corretas
const total = questions.length;
const acertos = questions.filter(q => q.user_answer === q.correct).length;
const score = Math.round((acertos / total) * 100);

// Tabela de XP
let xp = 0;
if (score === 100) xp = 35;
else if (score >= 70) xp = 20;
else if (score >= 50) xp = 10;
else xp = 5;

return {
  user_id,
  journey_day_id,
  questions,
  score,
  xp_earned: xp,
  acertos,
  total
};

